package com.skillpilot.backend.service;

import java.util.Map;

/**
 * Provider-neutral facade for reviewed learner-facing curriculum offerings.
 *
 * <p>Repository-backed runtimes resolve through registered composition views;
 * package-backed runtimes resolve through their authored offered scopes. The
 * personalization planner never scans files or derives choices from the skill
 * graph.</p>
 */
@FunctionalInterface
public interface CurriculumPersonalizationOfferingResolver {

    /**
     * Resolves one authored scope probe for a landscape.
     *
     * @return the scope of the reviewed resolved view, or {@code null} when
     *     the probe is not offered
     */
    Map<String, String> resolveScope(String landscapeId, Map<String, String> requestedScope);
}

}

interface ContentOffering {
  stages: Set<StageOffering>
  durationModels: Set<DurationModel>
}

const scriptDir = dirname(fileURLToPath(import.meta.url))
const repoRoot = resolve(scriptDir, '../..')
const shouldWrite = process.argv.includes('--write')
const shouldCheck = process.argv.includes('--check')

const qualityStatusPath = resolve(repoRoot, 'docs/qa-ci/status/curriculum-quality-status.json')
const durationPolicyPath = resolve(repoRoot, 'curricula/DE/Gymnasium/provenance/gymnasium-duration-model-policy.json')
const compositionViewRoot = resolve(repoRoot, 'curricula/DE/Gymnasium/composition-views')
const gymnasiumOverviewPath = resolve(repoRoot, 'curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_OVERVIEW.de.json')
const outputPath = resolve(repoRoot, 'app/src/generated/gymnasiumDurationOfferings.ts')
const durationModels: DurationModel[] = ['G8', 'G9']
const stageOfferings: StageOffering[] = ['SekI', 'SekII', 'CrossStage']

const readJson = <T>(path: string): T => JSON.parse(readFileSync(path, 'utf8')) as T

  return compositionViews.some((view) => view.subject === subject && scopeMatches(view.scope, requestedScope))
}

const loadGymnasiumJurisdictions = () => {
  const overview = readJson<GymnasiumOverview>(gymnasiumOverviewPath)
  return (overview.filters ?? [])
    .map((filter) => filter.id?.trim())
    .filter((id): id is string => !!id && /^DE-[A-Z]{2}$/u.test(id))
}

const isM6OrBetter = (maturity: string | undefined): boolean => maturity === 'M6' || maturity === 'M7'

const loadM6CanonicalGymnasiumSubjects = () => {
  const qualityStatus = readJson<CurriculumStatusDocument>(qualityStatusPath)
  const subjectToLandscapeId = new Map<string, string>()
  const landscapeIdToSubject = new Map<string, string>()

  for (const curriculum of qualityStatus.curricula ?? []) {
    if (!curriculum.subject || !curriculum.landscapeId) continue
    if (!isM6OrBetter(curriculum.maturity)) continue
    if (!curriculum.frameworkId?.startsWith('canonical-gymnasium')) continue
    subjectToLandscapeId.set(curriculum.subject, curriculum.landscapeId)
    landscapeIdToSubject.set(curriculum.landscapeId, curriculum.subject)
  }

  return { subjectToLandscapeId, landscapeIdToSubject }
}

const loadCompositionViews = (landscapeIdToSubject: Map<string, string>) => (
  collectFiles(compositionViewRoot, (path) => /\.view\.json$/iu.test(path))
    .map((viewPath) => {
      try {
        const view = readJson<CompositionView>(viewPath)
        const subject = view.landscapeId ? landscapeIdToSubject.get(view.landscapeId) : undefined
        if (!subject || !view.viewId || !view.scope) return null
        return { subject, viewId: view.viewId, scope: view.scope }
      } catch {
        return null
      }
    })
    .filter((view): view is CompositionViewSummary => view !== null)
)

if (!existsSync(qualityStatusPath)) {
  throw new Error(`Missing quality status: ${qualityStatusPath}`)
}
if (!existsSync(durationPolicyPath)) {
  throw new Error(`Missing duration policy: ${durationPolicyPath}`)
}
if (!existsSync(gymnasiumOverviewPath)) {
  throw new Error(`Missing Gymnasium overview: ${gymnasiumOverviewPath}`)
}

const { subjectToLandscapeId, landscapeIdToSubject } = loadM6CanonicalGymnasiumSubjects()
const compositionViews = loadCompositionViews(landscapeIdToSubject)
const jurisdictions = loadGymnasiumJurisdictions()
const policy = readJson<DurationPolicyDocument>(durationPolicyPath)
const offerings: Record<string, Record<string, Set<DurationModel>>> = {}
const contentOfferings: Record<string, Record<string, ContentOffering>> = {}

const addContentOffering = (
  landscapeId: string,
  jurisdiction: string,
  stage: StageOffering,
  durationModel?: DurationModel,
) => {
  const byJurisdiction = contentOfferings[landscapeId] ?? {}
  const current = byJurisdiction[jurisdiction] ?? {
    stages: new Set<StageOffering>(),
    durationModels: new Set<DurationModel>(),
  }
  current.stages.add(stage)
  if (durationModel) {
    current.durationModels.add(durationModel)
  }
  byJurisdiction[jurisdiction] = current
  contentOfferings[landscapeId] = byJurisdiction
}

for (const decision of policy.decisions ?? []) {
  if (decision.status !== 'reviewed') continue
  if (!stageTouchesSekI(decision.stage)) continue
  const subject = decision.subject
  const jurisdiction = decision.jurisdiction
  if (!subject || !jurisdiction) continue
  const landscapeId = subjectToLandscapeId.get(subject)
  if (!landscapeId) continue

  const offeredDurationModels = (decision.durationModels ?? [])
    .map(normalizeDurationModel)
    .filter((durationModel): durationModel is DurationModel => !!durationModel)
    .filter((durationModel) => hasRuntimeView(compositionViews, subject, {
      schoolForm: 'Gymnasium',
      jurisdiction,
      stage: 'SekI',
      durationModel,
    }))

  if (offeredDurationModels.length === 0) continue

  const byJurisdiction = offerings[landscapeId] ?? {}
  const current = byJurisdiction[jurisdiction] ?? new Set<DurationModel>()
  offeredDurationModels.forEach((durationModel) => current.add(durationModel))
  byJurisdiction[jurisdiction] = current
  offerings[landscapeId] = byJurisdiction
  offeredDurationModels.forEach((durationModel) => addContentOffering(landscapeId, jurisdiction, 'SekI', durationModel))
}

for (const [subject, landscapeId] of subjectToLandscapeId.entries()) {
  for (const jurisdiction of jurisdictions) {
    if (hasRuntimeView(compositionViews, subject, {
      schoolForm: 'Gymnasium',
      jurisdiction,
      stage: 'SekII',
      courseProfile: 'GK+LK',
    })) {
      addContentOffering(landscapeId, jurisdiction, 'SekII')
    }
    if (hasRuntimeView(compositionViews, subject, {
      schoolForm: 'Gymnasium',
      jurisdiction,
      stage: 'CrossStage',
      courseProfile: 'GK+LK',
    })) {
      addContentOffering(landscapeId, jurisdiction, 'CrossStage')
    }
  }
}

const sorted: Record<string, Record<string, DurationModel[]>> = {}
for (const landscapeId of Object.keys(offerings).sort()) {
  sorted[landscapeId] = {}
  for (const jurisdiction of Object.keys(offerings[landscapeId]).sort()) {
    sorted[landscapeId][jurisdiction] = durationModels.filter((durationModel) =>
      offerings[landscapeId][jurisdiction].has(durationModel),
    )
  }
}
const sortedContent: Record<string, Record<string, { stages: StageOffering[]; durationModels: DurationModel[] }>> = {}
for (const landscapeId of Object.keys(contentOfferings).sort()) {
  sortedContent[landscapeId] = {}
  for (const jurisdiction of Object.keys(contentOfferings[landscapeId]).sort()) {
    const current = contentOfferings[landscapeId][jurisdiction]
    sortedContent[landscapeId][jurisdiction] = {
      stages: stageOfferings.filter((stage) => current.stages.has(stage)),
      durationModels: durationModels.filter((durationModel) => current.durationModels.has(durationModel)),
    }
  }
}

  sourceGoal: SourceExtractionGoal,
  mapping: GoalMappingEntry,
  decisionBySourceGoalId: Map<string, SourceMappingReviewDecision>,
): { levels: Set<CourseLevelTag>; reviewedException: boolean } | null {
  const reviewDecision = sourceGoal.id ? decisionBySourceGoalId.get(sourceGoal.id) : undefined
  const levelDecision = mapping.courseLevelDecision ?? reviewDecision?.courseLevelDecision
  if (!levelDecision) return null

  const levels = new Set<CourseLevelTag>()
  addCourseLevelTokens(levels, levelDecision)
  if (levels.size === 0) return null

  const reviewedException = hasNonEmptyRationale(
    mapping.courseLevelRationale,
    reviewDecision?.courseLevelRationale,
    reviewDecision?.rationale,
  )
  return reviewedException ? { levels, reviewedException } : null
}

function isUpperSecondarySourceGoal(sourceGoal: SourceExtractionGoal): boolean {
  const values = [
    sourceGoal.stage,
    sourceGoal.phase,
    sourceGoal.sourcePath,
    sourceGoal.sourceRef,
    sourceGoal.passageId,
    sourceGoal.id,
  ]
    .filter((value): value is string => typeof value === 'string')
    .map((value) => value.toLowerCase())

  return values.some((value) =>
    value.includes('upper-secondary')
    || value.includes('sekii')
    || value.includes('sek ii')
    || value.includes('oberstufe')
    || value.includes('kursstufe')
    || value.includes('qualifikationsphase')
    || value.includes('studienstufe')
    || value.includes('gost')
    || value.includes('mss'))
}

function expectedCourseLevelsForSourceGoal(
  sourceGoal: SourceExtractionGoal,
  mapping: GoalMappingEntry,
  decisionBySourceGoalId: Map<string, SourceMappingReviewDecision>,
): { levels: Set<CourseLevelTag>; defaultedFromUnspecified: boolean; reviewedException: boolean } | null {
  if (!isUpperSecondarySourceGoal(sourceGoal)) return null

  const rawCourseLevel = typeof sourceGoal.courseLevel === 'string'
    ? sourceGoal.courseLevel.trim()
    : ''
  const normalized = rawCourseLevel.toUpperCase()
  const reviewedDecision = readReviewedCourseLevelDecision(sourceGoal, mapping, decisionBySourceGoalId)

  if (reviewedDecision) {
    return {
      levels: reviewedDecision.levels,
      defaultedFromUnspecified: false,
      reviewedException: reviewedDecision.reviewedException,
    }
  }

  if (normalized === 'UNSPECIFIED' || normalized === '') {
    return {
      levels: new Set<CourseLevelTag>(['GK', 'LK']),
      defaultedFromUnspecified: true,
      reviewedException: false,
    }
  }

  const levels = new Set<CourseLevelTag>()
  addCourseLevelTokens(levels, rawCourseLevel)
  return levels.size > 0
    ? { levels, defaultedFromUnspecified: false, reviewedException: false }
    : null
}

function formatCourseLevelSet(levels: Set<CourseLevelTag>): string {
  return Array.from(levels).sort().join('+') || '-'
}

export function evaluateCourseLevelMappingConsistency(
  landscape: SkillLandscape,
  mappingFiles: Array<GoalMappingFile & { file: string }> = readAllGoalMappingFiles(),
  sourceExtractionsByPath?: ReadonlyMap<string, SourceExtractionDocument>,
): RuleResult {
  const goalById = new Map(landscape.goals.map((goal) => [goal.id, goal]))
  const configuredMappingFiles = mappingFiles
    .filter((mappingFile) =>
      mappingFile.targetLandscapeId === landscape.landscapeId
      && typeof mappingFile.sourceExtractionPath === 'string'
      && mappingFile.sourceExtractionPath.trim().length > 0)

  if (configuredMappingFiles.length === 0) {
    return makeRule(
      'CQR-004',
      'not_configured',
      'No persisted source-extraction mapping with GK/LK course-level metadata is configured for this curriculum.',

    const upperSecondarySourceGoals = Array.from(sourceGoalById.values()).filter(isUpperSecondarySourceGoal)
    sourceGoals += upperSecondarySourceGoals.length
    upperSecondarySourceGoals.forEach((sourceGoal) => {
      const expected = expectedCourseLevelsForSourceGoal(sourceGoal, {}, groupedDecisions)
      if (!expected) return
      sourceGoalsWithCourseLevel += 1
      if (expected.levels.has('GK') && expected.levels.has('LK')) gkLkSourceGoals += 1
      if (!expected.levels.has('GK') && expected.levels.has('LK')) lkSourceGoals += 1
      if (String(sourceGoal.courseLevel ?? '').trim().toUpperCase() === 'UNSPECIFIED') unspecifiedSourceGoals += 1
      if (!mappedSourceGoalIds.has(sourceGoal.id!)) {
        const hasNeedsCanonicalGoalDecision = siblingMappingFiles.some((file) =>
          (file.decisions ?? []).some((decision) =>
            decision.sourceGoalId === sourceGoal.id && decision.decision === 'needsCanonicalGoal'))
        if (hasNeedsCanonicalGoalDecision) return
        unmappedCourseLevelSourceGoals += 1
        if (details.length < 20) details.push(`${sourceGoal.id}: no canonical mapping exists for course-level checked source goal`)
      }
    })
  }

  ;(mappingFile.mappings ?? []).forEach((mapping) => {
    if (mapping.matchType === 'partial') return
    if (!mapping.legacyGoalId || !mapping.canonicalGoalId) return

    const sourceGoal = sourceGoalById.get(mapping.legacyGoalId)
    if (!sourceGoal) {
      missingSourceGoals += 1
      if (details.length < 20) details.push(`${mappingFile.file}: source goal ${mapping.legacyGoalId} is not present in ${mappingFile.sourceExtractionPath}`)
      return
    }

    const expected = expectedCourseLevelsForSourceGoal(sourceGoal, mapping, decisionBySourceGoalId)
    if (!expected) return

    const targetGoal = goalById.get(mapping.canonicalGoalId)
    if (!targetGoal) {
      missingTargetGoals += 1
      if (details.length < 20) details.push(`${mappingFile.file}: canonical goal ${mapping.canonicalGoalId} is missing`)
      return
    }

    checkedMappingEdges += 1
    if (expected.defaultedFromUnspecified) defaultedUnspecifiedMappingEdges += 1
    if (expected.reviewedException) reviewedCourseLevelExceptions += 1

    const targetLevels = readEffectiveCanonicalGoalCourseLevels(targetGoal)
    const compatible = Array.from(expected.levels).every((level) => targetLevels.has(level))
    if (!compatible) {
      if (expected.reviewedException) return
      const message = `${sourceGoal.id} (${sourceGoal.courseLevel ?? 'unspecified'} -> ${formatCourseLevelSet(expected.levels)}) maps to ${formatGoal(targetGoal, targetGoal.id)} with tags ${formatCourseLevelSet(targetLevels)}`
      mismatches.push(message)
      if (details.length < 20) details.push(message)
    }
  })
})

const issueCount = mismatches.length + missingSourceGoals + missingTargetGoals + unmappedCourseLevelSourceGoals
return makeRule(
  'CQR-004',
  issueCount === 0 ? 'pass' : 'fail',
  issueCount === 0
    ? `Course-level mapping is clean for ${checkedMappingEdges} upper-secondary source-to-canonical mapping edge(s), including ${reviewedCourseLevelExceptions} reviewed course-level exception(s); unspecified upper-secondary source goals default to GK/LK unless explicitly reviewed.`
    : `${issueCount} upper-secondary course-level mapping issue(s); unspecified upper-secondary source goals default to GK/LK unless explicitly reviewed as LK-only.`,
  {
    configuredMappingFiles: configuredMappingFiles.length,
    sourceGoals,
    sourceGoalsWithCourseLevel,
    gkLkSourceGoals,
    lkSourceGoals,
    unspecifiedSourceGoals,
    checkedMappingEdges,
    defaultedUnspecifiedMappingEdges,
    reviewedCourseLevelExceptions,
    mismatches: mismatches.length,
    missingSourceGoals,

import { convertLearningGoal } from '../src/goalTypes'
import type { SkillLandscape } from '../src/landscapeTypes'
import { normalizeCompositionView } from '../src/utils/authoring/compositionViewAuthoring'
import { applyCompositionViewProjection } from '../src/utils/compositionViewRuntime'
import { buildDirectChildrenMap, getRenderedChildIds } from '../src/utils/treeProjectionRuntime'

/**
 * Returns canonical atomic goals that are learner-facing targets in one
 * composition view. `prerequisiteOnly` entries remain available to the
 * runtime prerequisite resolver, but are deliberately outside source-target
 * coverage for this view.
 */
export function collectAuthoritativeTargetAtomicGoalIds(
  landscape: SkillLandscape,
  rawView: unknown,
): Set<string> {
  const view = normalizeCompositionView(rawView)
  if (view.landscapeId !== landscape.landscapeId) return new Set<string>()

  const canonicalGoalById = new Map(landscape.goals.map((goal) => [goal.id, goal]))
  const entry = {
    meta: landscape,
    goals: landscape.goals.map((goal) => convertLearningGoal(goal, {
      landscapeId: landscape.landscapeId,
    })),
  }
  const projectedEntry = applyCompositionViewProjection([entry], view)[0]
  if (!projectedEntry) return new Set<string>()

  const projectedGoalById = new Map(projectedEntry.goals.map((goal) => [goal.id, goal]))
  const directChildrenByParent = buildDirectChildrenMap(projectedGoalById)
  const stack = projectedEntry.goals
    .filter((goal) => (goal.tags ?? []).includes('root'))
    .map((goal) => goal.id)
  const visited = new Set<string>()
  const targetAtomicGoalIds = new Set<string>()

  while (stack.length > 0) {
    const goalId = stack.pop()
    if (!goalId || visited.has(goalId)) continue
    visited.add(goalId)

    const canonicalGoal = canonicalGoalById.get(goalId)
    if (canonicalGoal && (canonicalGoal.contains?.length ?? 0) === 0) {
      targetAtomicGoalIds.add(goalId)
    }
    getRenderedChildIds(goalId, projectedGoalById, directChildrenByParent)
      .forEach((childId) => stack.push(childId))
  }

  return targetAtomicGoalIds
}
